# generated by `python -m Utils.sync` from curriculum/ -- edit there, not here
#
# POLYPHASE MERGE SORT  (Sorting / external)
#
# MENTAL MODEL
#   External sorting when you have a fixed, small number of tapes.
#   Distribute runs across tapes, merge two onto the third, repeat. True
#   polyphase splits runs in Fibonacci proportions so one tape empties
#   exactly as a merge completes, removing the rewind pass.
#
# INVARIANT
#   Each tape holds a sequence of internally-sorted runs; each merge pass
#   halves the run count and at least one tape becomes empty.
#
# COMPLEXITY  best O(n log n) | avg O(n log n) | worst O(n log n)
# SPACE       O(run_size) in memory
# PROPERTIES  stable no  in-place no  adaptive no
#
# REACH FOR IT WHEN
#   Historical interest, and any setting with a hard cap on simultaneous
#   output streams.
#
# AVOID WHEN
#   Modern storage with random access — plain external merge sort is simpler
#   and faster.
#
# PITFALLS
#   1. A tape holds a SEQUENCE of runs, not one sorted stream. Merging two
#      tapes as if each were a single sorted stream produces silently
#      unsorted output — which is what this file did before it was fixed.
#      Run boundaries are found by detecting a descent in value.
#   2. This implementation is the simpler *balanced* 3-tape merge, not true
#      Fibonacci polyphase. The distinction is the whole point of the name,
#      so do not claim the latter in an interview.
#   3. Termination is 'one tape left holding ONE run', not 'one tape left'.
#      Stopping at the weaker condition emits a partially sorted file.
#   4. Empty input used to loop forever here: no tape ever became non-empty,
#      so the terminating condition was unreachable.
#   5. Hard-coded tape filenames in the working directory made two
#      concurrent sorts silently corrupt each other.
#
# SEE ALSO    external_merge_sort, merge_sort
#
# INTERVIEW
#   - Tape-based sorting history; why Fibonacci numbers appear in it
# --- end curriculum ---

"""
Polyphase merge sort — tape-era external sorting, balanced 3-tape form.

Honest scope note: a *true* polyphase sort distributes the initial runs across
tapes in Fibonacci proportions so that one tape empties exactly as a merge
completes, which removes the separate redistribution pass. This implementation is
the simpler balanced 3-tape scheme: alternate runs onto two tapes, merge them
onto the third, then redistribute and repeat. That redistribution pass is
precisely the cost polyphase exists to eliminate, so seeing it here is the point.

The crucial detail, and the thing the first version of this file got wrong: a
tape holds a SEQUENCE of sorted runs, not one sorted stream. Merging two tapes
therefore means merging them run by run, and run boundaries are found by
detecting a descent in value.
"""

import os
import tempfile
from typing import TextIO

DEFAULT_RUN_SIZE = 3
TAPE_NAMES = ("tapeA.txt", "tapeB.txt", "tapeC.txt")


def _read_value(handle: TextIO) -> int | None:
    """Next integer from `handle`, or None at end of file. Blank lines are skipped."""
    line = handle.readline()
    while line and not line.strip():
        line = handle.readline()
    return int(line.strip()) if line else None


class _TapeReader:
    """
    Streams one tape, exposing it as a sequence of sorted runs.

    A run ends at the first descent: if the next value is smaller than the
    current one it belongs to the following run. `begin_run` opens the next run,
    `value` peeks at the current element, `advance` consumes it.
    """

    def __init__(self, path: str) -> None:
        self._handle = open(path, encoding="utf-8")
        self._current = _read_value(self._handle)
        self._in_run = False

    @property
    def value(self) -> int | None:
        """Current element of the open run, or None once the run has ended."""
        return self._current if self._in_run else None

    @property
    def exhausted(self) -> bool:
        return self._current is None

    def begin_run(self) -> bool:
        """Open the next run. Returns False when the tape has no runs left."""
        if self._current is None:
            self._in_run = False
            return False
        self._in_run = True
        return True

    def advance(self) -> None:
        """Consume the current element, closing the run on a descent."""
        previous = self._current
        self._current = _read_value(self._handle)
        if self._current is None or (previous is not None and self._current < previous):
            self._in_run = False

    def close(self) -> None:
        self._handle.close()


def distribute_runs(input_file: str, run_size: int, tape_a: str, tape_b: str) -> int:
    """
    Build the initial runs and deal them alternately onto two tapes.

    Each block of `run_size` lines is sorted in memory — the only point where the
    algorithm needs RAM proportional to anything at all.

    Returns the number of runs written.

    Time:  O(n log(run_size))
    Space: O(run_size)
    """
    runs = 0
    with open(input_file, encoding="utf-8") as f, \
         open(tape_a, "w", encoding="utf-8") as a, \
         open(tape_b, "w", encoding="utf-8") as b:
        use_a = True
        while True:
            chunk: list[int] = []
            for _ in range(run_size):
                line = f.readline()
                if not line:
                    break
                line = line.strip()
                if line:
                    chunk.append(int(line))
            if not chunk:
                break
            chunk.sort()
            out = a if use_a else b
            out.write("".join(f"{num}\n" for num in chunk))
            use_a = not use_a
            runs += 1
    return runs


def split_runs(source: str, tape_a: str, tape_b: str) -> int:
    """
    Deal the runs already present on `source` alternately onto two tapes.

    This is the redistribution pass: it reads and writes the whole file while
    doing no merging at all. That pure overhead is exactly what the Fibonacci
    distribution in real polyphase sort is designed to avoid.

    Returns the number of runs written.

    Time:  O(n) I/O
    Space: O(1)
    """
    reader = _TapeReader(source)
    runs = 0
    try:
        with open(tape_a, "w", encoding="utf-8") as a, \
             open(tape_b, "w", encoding="utf-8") as b:
            use_a = True
            while reader.begin_run():
                out = a if use_a else b
                while reader.value is not None:
                    out.write(f"{reader.value}\n")
                    reader.advance()
                use_a = not use_a
                runs += 1
    finally:
        reader.close()
    return runs


def merge_runs(tape_a: str, tape_b: str, tape_out: str) -> int:
    """
    Merge `tape_a` and `tape_b` onto `tape_out`, one run from each per output run.

    Returns the number of runs written, which is how the caller knows whether the
    data has collapsed to a single sorted run and the sort is done.

    Time:  O(n) comparisons per pass
    Space: O(1) — one pending value per tape
    """
    a = _TapeReader(tape_a)
    b = _TapeReader(tape_b)
    runs = 0
    try:
        with open(tape_out, "w", encoding="utf-8") as out:
            while True:
                has_a = a.begin_run()
                has_b = b.begin_run()
                if not has_a and not has_b:
                    break
                runs += 1
                while a.value is not None or b.value is not None:
                    take_a = b.value is None or (a.value is not None and a.value <= b.value)
                    source = a if take_a else b
                    out.write(f"{source.value}\n")
                    source.advance()
    finally:
        a.close()
        b.close()
    return runs


def polyphase_sort(
    input_file: str,
    output_file: str,
    run_size: int = DEFAULT_RUN_SIZE,
    work_dir: str | None = None,
) -> None:
    """
    Sort a newline-delimited file of integers using three tapes as scratch space.

    `work_dir` holds the tapes; when omitted a temporary directory is created and
    removed, leaving nothing behind but `output_file`.

    Time:  O(n log(runs)) comparisons over O(log(runs)) merge passes
    Space: O(run_size) in memory, O(n) on disk

    Three bugs fixed versus the original: tapes are merged run by run rather than
    as single sorted streams (which produced silently unsorted output), empty
    input no longer loops forever, and the tape paths are no longer hard-coded
    into the current working directory where concurrent sorts would collide.
    """
    owns_work_dir = work_dir is None
    work_dir = work_dir or tempfile.mkdtemp(prefix="polyphase_")
    tape_a, tape_b, tape_c = (os.path.join(work_dir, name) for name in TAPE_NAMES)

    try:
        if distribute_runs(input_file, run_size, tape_a, tape_b) == 0:
            # Empty input. The original spun forever here, waiting for a tape to
            # become non-empty when none ever would.
            open(output_file, "w", encoding="utf-8").close()
            return

        while True:
            run_count = merge_runs(tape_a, tape_b, tape_c)
            if run_count <= 1:
                os.replace(tape_c, output_file)
                return
            split_runs(tape_c, tape_a, tape_b)
    finally:
        for tape in (tape_a, tape_b, tape_c):
            if os.path.exists(tape):
                os.remove(tape)
        if owns_work_dir:
            try:
                os.rmdir(work_dir)
            except OSError:
                pass
